 public:
  LiveBroadcastLiveBroadcastServer() = default;
  ~LiveBroadcastLiveBroadcastServer() override = default;

  // RPC方法实现
  InsErrorCode LiveBroadcastPrepare() override;
  InsErrorCode LiveBroadcastStart() override;
