                             const WifiInfo& wifi_info) override;
  void OnTopicWifiStaAutoConnect(WifiConnectionResult error_code,
                                 const WifiInfo& wifi_info) override;
  void OnTopicWifiStaOff(InsErrorCode error_code) override;
};

