#include "stream/nalu_reader.h"

#include <algorithm>
#include <cstring>

#include "ins_base/log.h"
#include "ins_error_code/ins_errorcode.h"
namespace ins {
namespace live_broadcast {

NaluReader::NaluReader() {}

NaluReader::~NaluReader() {}

int NaluReader::FindStartCode(const uint8_t* buf, int32_t size,
                              int32_t& start_code_size) {
  for (int32_t i = 0; i < size - 2; ++i) {
    if (buf[i] == 0x00 && buf[i + 1] == 0x00 && buf[i + 2] == 0x01) {
      start_code_size = 3;
      return i;
    }
    if (i < size - 3 && buf[i] == 0x00 && buf[i + 1] == 0x00 &&
        buf[i + 2] == 0x00 && buf[i + 3] == 0x01) {
      start_code_size = 4;
      return i;
    }
  }
  return -1;
}

InsErrorCode NaluReader::ReadNalu(const uint8_t* stream_data, int32_t size,
                                  std::vector<Nalu>& nalu) {
  if (stream_data == nullptr || size <= 0) {
    return kInsErrorCode_LiveBroadcast_InvalidParam;
  }

  nalu.clear();

  int32_t start_pos = -1;
  int32_t start_code_size = 0;

  // 如果单次输入就超过了最大缓冲大小，直接报错，避免无意义的内存拷贝和潜在的OOM,
  // 或者输入数据无效
  if (static_cast<size_t>(size) > kMaxPendingSize || size < 4) {
    ILOGS_E << "input size exceeds limit: " << size;
    return kInsErrorCode_LiveBroadcast_InvalidParam;
  }

  if (pending_data_.size() + static_cast<size_t>(size) > kMaxPendingSize) {
    ILOGS_E << "pending_data_ size exceeds limit: "
            << pending_data_.size() + static_cast<size_t>(size);
    // 超过限制，清空缓存，避免内存无限制增长, 清空后，重新插入新的数据,
    // 避免数据丢失
    pending_data_.clear();
  }

  // 将新的数据插入到缓存中
  pending_data_.insert(pending_data_.end(), stream_data, stream_data + size);

  // 循环处理缓存中的数据，直到缓存为空
  while (!pending_data_.empty()) {
    // 尝试在缓存中寻找起始码，
    // start_pos为起始码在缓存中的位置，start_code_size为起始码的长度
    start_pos = FindStartCode(pending_data_.data(),
                              static_cast<int32_t>(pending_data_.size()),
                              start_code_size);

    // -1表示未找到起始码
    if (start_pos != -1) {
      // 找到起始码。
      // 如果起始码在缓存中的位置大于0，则丢弃起始码之前的垃圾数据
      if (start_pos > 0) {
        // 优化：只有当需要移除的数据量较大时才进行erase，避免频繁小内存搬移
        // 或者在环形缓冲区实现前，仍需erase以保持逻辑正确性，但已增加上限保护
        pending_data_.erase(pending_data_.begin(),
                            pending_data_.begin() + start_pos);
        start_pos = 0;
      }
    } else {
      // 丢弃除最后3字节外的所有数据（防止分割起始码）

