// Copyright (c) 2025 Insta360. All rights reserved.
//
// ins_livecast 进程主入口
// 注意：进程名为 ins_livecast（15字符限制），但模块名保持 ins_live_broadcast
//
// 功能说明：
// - 初始化 ibus 服务
// - 初始化直播服务（单例）
// - 注册 TerminateSignal 处理 SIGINT/SIGTERM，主线程轮询运行标志后调用
//   Shutdown() 做优雅收尾

#include <atomic>
#include <chrono>
#include <memory>
#include <thread>
#include <vector>

#include "ibus/live_broadcast_ibus_impl.h"
#include "ibus_service.h"
#include "ins_base/log.h"
#include "ins_base/signal_dispatcher.h"
#include "ins_base/thread.h"
#include "ins_error_code/ins_errorcode.h"
#include "ins_error_code_string.h"
#include "service/live_broadcast_service.h"

namespace {
constexpr uint32_t kMainLoopSleepMilliseconds = 1000;
/// 收到 TerminateSignal 后，等待状态机回到 Idle
/// 的最大时长（毫秒），超时后仍会继续回收
constexpr uint32_t kShutdownWaitIdleMilliseconds = 20000;
}  // namespace

namespace {
#ifdef LOG_TAG
#undef LOG_TAG
#endif
#define LOG_TAG \
  "ins_livecast"  // 与进程名保持一致，便于日志检索和ShareState权限匹配
}  // namespace

int main() {
  ILOGS_I << "ins_livecast starting...";

  // 运行标志，供 TerminateSignal 回调置位以触发主线程退出
  auto running = std::make_shared<std::atomic<bool>>(true);
  ins::base::TerminateSignal([running](int signo) {
    ILOGS_I << "Received termination signal " << signo << " ("
            << ins::base::GetSignalName(signo) << "), initiating shutdown...";
    running->store(false, std::memory_order_release);
  });

  std::vector<std::unique_ptr<::erpc::Service>> ibus_services;

  auto rpc_server = std::make_unique<
      ::ins::ibus::camera::live_broadcast::LiveBroadcastLiveBroadcastServer>();
  auto config_sub =
      std::make_unique<::ins::ibus::camera::config::ConfigSubscriber>();
  auto netd_sub =
      std::make_unique<::ins::ibus::camera::netd::NetdSubscriber>();
  auto mediad_sub =
      std::make_unique<::ins::ibus::camera::mediad::MediadSubscriber>();

  ibus_services.push_back(std::move(rpc_server));
  ibus_services.push_back(std::move(config_sub));
  ibus_services.push_back(std::move(netd_sub));
  ibus_services.push_back(std::move(mediad_sub));

  InsErrorCode error_code =
      ::ins::ibus::IbusService::GetInstance().Initialize(
          std::move(ibus_services), nullptr);
  if (kInsErrorCode_Comm_Success != error_code) {
    ILOGS_E << "Failed to initialize ibus service, error_code: "
            << ins::errc::GetInsErrorCodeString(error_code) << " ("
            << static_cast<int32_t>(error_code) << ")";
    return static_cast<int>(error_code);
  }

  auto& service = ins::live_broadcast::LiveBroadcastService::GetInstance();
  InsErrorCode ret = service.Init();
  if (ret != kInsErrorCode_Comm_Success) {
    ILOGS_E << "LiveBroadcastService init failed: "
            << ins::errc::GetInsErrorCodeString(ret) << " ("
            << static_cast<int32_t>(ret) << ")";
    return static_cast<int>(ret);
  }

  ret = service.Start();
  if (ret != kInsErrorCode_Comm_Success) {
    ILOGS_E << "LiveBroadcastService start failed: "
            << ins::errc::GetInsErrorCodeString(ret) << " ("
            << static_cast<int32_t>(ret) << ")";
    return static_cast<int>(ret);
  }

  ILOGS_I << "LiveBroadcastService started successfully.";
  ILOGS_I << "Waiting for termination signal (SIGTERM/SIGINT)...";

  ins::base::Thread main_loop_thread("LivecastMainLoop", [running]() {
    if (!running->load(std::memory_order_acquire)) {
      return false;
    }
    std::this_thread::sleep_for(
        std::chrono::milliseconds(kMainLoopSleepMilliseconds));
    return running->load(std::memory_order_acquire);
  });
  if (main_loop_thread.Start() != kInsErrorCode_Comm_Success) {
    ILOGS_E << "Failed to start main loop thread";
    return static_cast<int>(kInsErrorCode_Comm_Enomem);
  }
  main_loop_thread.Join();

  ILOGS_I << "Shutdown signal received, starting graceful shutdown...";
  service.Shutdown(kShutdownWaitIdleMilliseconds);
  ILOGS_I << "ins_livecast process exiting gracefully.";
  return 0;
}

