#include "state_machine/live_state_prepare.h"
#include "state_machine/live_state_running.h"
#include "state_machine/live_state_stopping.h"

namespace ins {
namespace live_broadcast {

namespace {
#ifdef LOG_TAG
#undef LOG_TAG
#endif
#define LOG_TAG "LiveStateStarting"
}  // namespace

LiveStateStarting::LiveStateStarting()
    : LiveStateMachine(LiveBroadcastState::kStarting) {}

void LiveStateStarting::OnEntry() {
  ILOGS_I << "Entering Starting state";

  if (!manager_) {
    ILOGS_E << "Manager not set, cannot start";
    ChangeState<LiveStateStopping>();
    return;
  }
  if (!config_manager_) {
    ILOGS_E << "ConfigManager not set, cannot start";
    manager_->ReportLiveBroadcastErrorCode(
        LiveBroadcastErrorCode::kSystemError);
    ChangeState<LiveStateStopping>();
    return;
  }

  std::string rtmp_url = config_manager_->GetRtmpUrl();
  if (rtmp_url.empty()) {
    ILOGS_E << "RTMP URL is empty";
    manager_->ReportLiveBroadcastErrorCode(
        LiveBroadcastErrorCode::kSystemError);
    ChangeState<LiveStateStopping>();
    return;
  }

  std::shared_ptr<RtmpPusher> pusher = std::make_shared<RtmpPusher>();
  if (stream_controller_) {
    pusher->SetStreamController(stream_controller_);
    stream_controller_->SwitchToLiveMode();
    ILOGS_I << "Switched to live mode";
  }
  manager_->SetLiveBroadcastRtmpPusher(pusher);

  const uint64_t attempt_id = manager_->BeginStartAttempt();

  std::weak_ptr<LiveBroadcastManager> weak_mgr = manager_;
  const bool started =
      manager_->StartConnectThread([weak_mgr, pusher, rtmp_url, attempt_id]() {
        InsErrorCode err = pusher->Connect(rtmp_url);
        auto mgr = weak_mgr.lock();
        if (!mgr) {
          // Stop/Shutdown 已开始；此时不再回投结果，由连接线程自己清理。
          pusher->Disconnect();
          return;
        }

        std::string msg = (err != kInsErrorCode_Comm_Success)
                              ? ins::errc::GetInsErrorCodeString(err)
                              : "";
        mgr->PostStartResult(attempt_id, err, msg);
      });
  if (!started) {
    ILOGS_E << "Failed to start connect thread";
    manager_->ReportLiveBroadcastErrorCode(
        LiveBroadcastErrorCode::kSystemError);
    ChangeState<LiveStateStopping>();
  }
}

void LiveStateStarting::OnExit() { ILOGS_I << "Exiting Starting state"; }

void LiveStateStarting::OnEvent(const EventStartSuccess& event) {
  ILOGS_I << "Received EventStartSuccess in Starting state";

  // RTMP连接成功且流启动，转换到Running状态
  ChangeState<LiveStateRunning>();
  static_cast<void>(event);
}

void LiveStateStarting::OnEvent(const EventStartFailed& event) {
  ILOGS_E << "Received EventStartFailed in Starting state, error_code="
          << static_cast<int32_t>(event.error_code)
          << ", message=" << event.message;

  // 错误码已由 OnDispatchStartResult 上报，此处仅做状态转换；失败转 Prepare
  ChangeState<LiveStatePrepare>();
  static_cast<void>(event);
}

void LiveStateStarting::OnEvent(const EventError& event) {
  ILOGS_E << "Received EventError in Starting state, error_code="
          << static_cast<int32_t>(event.error_code)
          << ", message=" << event.message;

  // 发布错误码Topic
  if (manager_) {
    manager_->ReportLiveBroadcastErrorCode(event.error_code);
  } else {
    ILOGS_E << "Manager not set, cannot report error";
  }

  // 错误发生，进入Stopping状态
  ChangeState<LiveStateStopping>();
}

void LiveStateStarting::OnEvent(const EventStopRequest& event) {
  ILOGS_I << "Received EventStopRequest in Starting state, reason="
          << static_cast<int32_t>(event.reason);

  // 停止请求，进入Stopping状态
  ChangeState<LiveStateStopping>();
}

}  // namespace live_broadcast
}  // namespace ins

