48	  const std::string trimmed_url = ins::base::StringHelper::Trim(rtmp_url);
49	  const InsErrorCode validate_result = ValidateRtmpUrl(trimmed_url);
50	  if (validate_result != kInsErrorCode_Comm_Success) {
51	    return validate_result;
52	  }
53	
54	  InsErrorCode copy_result = kInsErrorCode_Comm_Success;
55	  const InsErrorCode update_result =
56	      ins::bll::ConfigParamController::GetInstance()
57	          .SetGeneralConfig<ins::config::ConfigKey::kLiveBroadcast>(
58	              [&trimmed_url, &copy_result](
59	                  ins::config::LiveBroadcastConfig& config) noexcept {
60	                copy_result = ins::base::StringHelper::CopyStringToArray(
61	                    trimmed_url, config.rtmp_address);
62	              });
63	  if (copy_result != kInsErrorCode_Comm_Success) {
64	    ILOGS_E << "Failed to copy RTMP url into config buffer, error_code="
65	            << static_cast<int32_t>(copy_result);
66	    return copy_result;
67	  }
68	
69	  if (update_result != kInsErrorCode_Comm_Success) {
70	    ILOGS_E << "Failed to update live broadcast url config, error_code="
71	            << static_cast<int32_t>(update_result);
72	    return update_result;
73	  }
74	
75	  const auto readback_result =
76	      ins::bll::ConfigParamController::GetInstance()
77	          .GetGeneralConfig<ins::config::ConfigKey::kLiveBroadcast>();
78	  if (!readback_result.has_value()) {
79	    ILOGS_E << "Failed to read back live broadcast url config, error_code="
80	            << ins::errc::GetInsErrorCodeString(readback_result.error()) << " ("
81	            << static_cast<int32_t>(readback_result.error()) << ")";
82	    return readback_result.error();
83	  }
84	
85	  const std::string stored_url = ins::base::StringHelper::ConvertArrayToString(
86	      readback_result.value().rtmp_address);
87	  if (stored_url != trimmed_url) {
88	    ILOGS_E << "Live broadcast url read back mismatch, expected_length="
89	            << trimmed_url.size() << ", actual_length=" << stored_url.size();
90	    return kInsErrorCode_Comm_Eio;
91	  }
92	
93	  return kInsErrorCode_Comm_Success;
