99	    ILOGS_E << "Wi-Fi SSID is empty";
100	    return kInsErrorCode_LiveBroadcast_InvalidParam;
101	  }
102	
103	  if (password.empty()) {
104	    return NetdWifiStaClient::GetInstance().WifiStaOnNoPasswd(
105	        OperateOwner::kLive, OperateMode::kAsync, ssid, "");
106	  }
107	
108	  return NetdWifiStaClient::GetInstance().WifiStaOn(
109	      OperateOwner::kLive, OperateMode::kAsync, ssid, password, "",
110	      ins::ibus::common::netd::WifiChannel::kChannelAuto);
111	}
