113	InsErrorCode InsLivecastCli::ValidateRtmpUrl(
114	    const std::string& rtmp_url) const {
115	  if (ins::base::StringHelper::IsEmptyOrWhitespace(rtmp_url)) {
116	    ILOGS_E << "RTMP url is empty";
117	    return kInsErrorCode_LiveBroadcast_InvalidUrl;
118	  }
119	
120	  const bool is_rtmp = ins::base::StringHelper::StartsWith(rtmp_url, "rtmp://");
121	  const bool is_rtmps =
122	      ins::base::StringHelper::StartsWith(rtmp_url, "rtmps://");
123	  if (!is_rtmp && !is_rtmps) {
124	    ILOGS_E << "RTMP url must start with rtmp:// or rtmps://";
125	    return kInsErrorCode_LiveBroadcast_InvalidUrl;
126	  }
127	
128	  if (rtmp_url.size() >= ins::config::kMaxRtmpAddressLen) {
129	    ILOGS_E << "RTMP url exceeds max length: " << rtmp_url.size();
130	    return kInsErrorCode_Comm_Erange;
131	  }
132	
133	  return kInsErrorCode_Comm_Success;
134	}
