InsLivecastCli::LiveBroadcastGetState() const {
  LiveBroadcastStateInfo state_info{};
  const InsErrorCode result =
      LiveBroadcastClient::GetInstance().LiveBroadcastGetState(state_info);
  if (result != kInsErrorCode_Comm_Success) {
    return tl::unexpected(result);
  }
  return state_info;
}

InsErrorCode InsLivecastCli::SetLiveBroadcastUrl(
    const std::string& rtmp_url) const {
  const std::string trimmed_url = ins::base::StringHelper::Trim(rtmp_url);
  const InsErrorCode validate_result = ValidateRtmpUrl(trimmed_url);
  if (validate_result != kInsErrorCode_Comm_Success) {
    return validate_result;
  }

  InsErrorCode copy_result = kInsErrorCode_Comm_Success;
  const InsErrorCode update_result =
      ins::bll::ConfigParamController::GetInstance()
          .SetGeneralConfig<ins::config::ConfigKey::kLiveBroadcast>(
              [&trimmed_url, &copy_result](
                  ins::config::LiveBroadcastConfig& config) noexcept {
                copy_result = ins::base::StringHelper::CopyStringToArray(
                    trimmed_url, config.rtmp_address);
              });
  if (copy_result != kInsErrorCode_Comm_Success) {
    ILOGS_E << "Failed to copy RTMP url into config buffer, error_code="
            << static_cast<int32_t>(copy_result);
    return copy_result;
  }

  if (update_result != kInsErrorCode_Comm_Success) {
    ILOGS_E << "Failed to update live broadcast url config, error_code="
            << static_cast<int32_t>(update_result);
    return update_result;
  }

  const auto readback_result =
      ins::bll::ConfigParamController::GetInstance()
          .GetGeneralConfig<ins::config::ConfigKey::kLiveBroadcast>();
  if (!readback_result.has_value()) {
    ILOGS_E << "Failed to read back live broadcast url config, error_code="
            << ins::errc::GetInsErrorCodeString(readback_result.error()) << " ("
            << static_cast<int32_t>(readback_result.error()) << ")";
    return readback_result.error();
  }

  const std::string stored_url = ins::base::StringHelper::ConvertArrayToString(
      readback_result.value().rtmp_address);
  if (stored_url != trimmed_url) {
    ILOGS_E << "Live broadcast url read back mismatch, expected_length="
            << trimmed_url.size() << ", actual_length=" << stored_url.size();
    return kInsErrorCode_Comm_Eio;
  }

  return kInsErrorCode_Comm_Success;
}

InsErrorCode InsLivecastCli::SetConnectWifi(const std::string& ssid,
                                            const std::string& password) const {
  if (ssid.empty()) {
    ILOGS_E << "Wi-Fi SSID is empty";
    return kInsErrorCode_LiveBroadcast_InvalidParam;
  }

  if (password.empty()) {
    return NetdWifiStaClient::GetInstance().WifiStaOnNoPasswd(
        OperateOwner::kLive, OperateMode::kAsync, ssid, "");
  }

  return NetdWifiStaClient::GetInstance().WifiStaOn(
      OperateOwner::kLive, OperateMode::kAsync, ssid, password, "",
      ins::ibus::common::netd::WifiChannel::kChannelAuto);
}

InsErrorCode InsLivecastCli::ValidateRtmpUrl(
    const std::string& rtmp_url) const {
  if (ins::base::StringHelper::IsEmptyOrWhitespace(rtmp_url)) {
    ILOGS_E << "RTMP url is empty";
    return kInsErrorCode_LiveBroadcast_InvalidUrl;
  }

  const bool is_rtmp = ins::base::StringHelper::StartsWith(rtmp_url, "rtmp://");
  const bool is_rtmps =
      ins::base::StringHelper::StartsWith(rtmp_url, "rtmps://");
  if (!is_rtmp && !is_rtmps) {
    ILOGS_E << "RTMP url must start with rtmp:// or rtmps://";
    return kInsErrorCode_LiveBroadcast_InvalidUrl;
  }

  if (rtmp_url.size() >= ins::config::kMaxRtmpAddressLen) {
    ILOGS_E << "RTMP url exceeds max length: " << rtmp_url.size();
    return kInsErrorCode_Comm_Erange;
  }

  return kInsErrorCode_Comm_Success;
}

}  // namespace ins::live_broadcast::cli

