#include <cstdint>
#include <iostream>
#include <memory>
#include <vector>

#include "cli_terminal.h"
#include "command_manager.h"
#include "ibus_diagnostic_common.h"
#include "ibus_service.h"
#include "ins_base/log.h"
#include "ins_error_code/ins_errorcode.h"
#include "ins_error_code_string.h"

namespace {

InsErrorCode InitializeIbus() {
  INS_IBUS_INIT_INFO_LOG();

  std::vector<std::unique_ptr<::erpc::Service>> services;

  InsErrorCode init_result = ::ins::ibus::IbusService::GetInstance().Initialize(
      std::move(services), nullptr);
  if (init_result != kInsErrorCode_Comm_Success) {
    ILOGS_E << "Failed to initialize ibus with dynamic address, reason="
            << ins::errc::GetInsErrorCodeString(init_result) << " ("
            << static_cast<int32_t>(init_result) << ")";
    return init_result;
  }

  return kInsErrorCode_Comm_Success;
}

}  // namespace

int main() {
  const InsErrorCode init_result = InitializeIbus();
  if (init_result != kInsErrorCode_Comm_Success) {
    std::cout << "Ibus init failed: "
              << ins::errc::GetInsErrorCodeString(init_result) << " ("
              << init_result << ")\n";
    return -1;
  }

  ins::live_broadcast::cli::CommandManager::GetInstance().InitializeCommands();
  ins::live_broadcast::cli::CliTerminal terminal(true);

  ILOGS_I << "ins_livecast_cli started";
  std::cout << "ins_livecast_cli started. Type 'help' for commands.\n";

  while (true) {
    const auto input = terminal.Input("ins-livecast> ");
    if (!input.has_value()) {
      break;
    }
    if (!terminal.HandleLine(input.value())) {
      break;
    }
  }

  ILOGS_I << "ins_livecast_cli exiting";
  return 0;
}

