namespace ins::live_broadcast::cli {

namespace {

std::string GetHistoryFilePath() {
  const char* home_dir = std::getenv("HOME");
  if (home_dir == nullptr) {
    ILOGS_W << "HOME environment variable not set, command history will not "
               "persist";
    return "";
  }

  std::error_code error_code;
  const std::filesystem::path history_dir =
      std::filesystem::path(home_dir) / ".config" / "ins_livecast_cli";

  if (!std::filesystem::exists(history_dir, error_code) || error_code) {
    ILOGS_W << "History directory does not exist: " << history_dir
            << ", command history will not persist";
    return "";
  }

  return (history_dir / "history.txt").string();
}

void PrintUsageText(const commands::ICommand& command,
                    const std::vector<std::string>& args) {
  const std::string usage = command.GetUsage(args);
  if (usage.empty()) {
    return;
  }
  std::cout << usage;
  if (usage.back() != '\n') {
    std::cout << '\n';
  }
}

}  // namespace

CliTerminal::CliTerminal(bool persist_history)
    : persist_history_(persist_history) {
  if (persist_history_) {
    history_file_path_ = GetHistoryFilePath();
  }

  replxx_.set_max_history_size(100);
  replxx_.set_max_hint_rows(4);

  if (persist_history_ && !history_file_path_.empty()) {
    replxx_.history_load(history_file_path_);
  }

  replxx_.set_completion_callback(
      [this](const std::string& context, int& context_len) {
        ReplxxCompletions completions;
        CompletionHook(context, context_len, completions);
        return completions;
      });

  replxx_.set_hint_callback([this](const std::string& context, int& context_len,
                                   replxx::Replxx::Color& color) {
    ReplxxHints hints;
    HintHook(context, context_len, color, hints);
    return hints;
  });

  replxx_.set_highlighter_callback(
      [this](const std::string& context, ReplxxColors& colors) {
        HighlightHook(context, colors);
      });

  replxx_.set_word_break_characters(" \t\n\r");
  replxx_.set_completion_count_cutoff(64);
  replxx_.set_double_tab_completion(false);
  replxx_.set_complete_on_empty(true);
  replxx_.set_beep_on_ambiguous_completion(false);

  replxx_.bind_key_internal(replxx::Replxx::KEY::control('R'),
                            "history_incremental_search");
  replxx_.bind_key_internal(replxx::Replxx::KEY::control('L'), "clear_screen");
}

std::optional<std::string> CliTerminal::Input(const char* prompt) {
  const char* line = replxx_.input(prompt);
  if (line == nullptr) {
    return std::nullopt;
  }

  std::string input_line(line);
  if (!input_line.empty()) {
    replxx_.history_add(input_line);
    if (persist_history_ && !history_file_path_.empty()) {
      replxx_.history_sync(history_file_path_);
    }
  }

  return input_line;
}

bool CliTerminal::HandleLine(const std::string& line) {
  if (line.empty()) {
    return true;
  }

  const auto args = ins::base::cli_utility::ParseLine(line);

