bool IsLiveInfoAlias(const std::string& token) {
  const auto* cmd =
      ins::live_broadcast::cli::CommandManager::GetInstance().GetCommand(token);
  return cmd != nullptr && cmd->GetName() == "live_info";
}

std::vector<std::string> NormalizeLiveInfoArgs(
    const std::vector<std::string>& args) {
  std::vector<std::string> normalized_args = args;
  if (!normalized_args.empty() && normalized_args[0] != "live_info" &&
      IsLiveInfoAlias(normalized_args[0])) {
    normalized_args.insert(normalized_args.begin(), "live_info");
  }
  return normalized_args;
}

void PrintRpcFailureHint(InsErrorCode result) {
  if (result == kInsErrorCode_Ibus_Timeout) {
    std::cout << "RPC request timed out. Please check whether ins_livecast is "
                 "running "
                 "and initialized correctly.\n";
  }
}

}  // namespace

namespace ins::live_broadcast::cli::commands {

CommandResult LiveInfoCommand::Execute(const std::vector<std::string>& args) {
  if (args.empty()) {
    return CommandResult::kUsageError;
  }

  std::vector<std::string> normalized_args = NormalizeLiveInfoArgs(args);
  if (normalized_args[0] != "live_info") {
    std::cout << "未知命令: " << normalized_args[0] << '\n';
    return CommandResult::kUsageError;
  }

  if (normalized_args.size() >= 2 && normalized_args[1] == "get_state") {
    return HandleGetState(normalized_args);
  }

  std::cout << "未知的 live_info 子命令\n";
  return CommandResult::kUsageError;
}

