// ① 6 个 RPC 的薄封装：直接持单例 Client，语义与服务端一一对应
InsErrorCode InsLivecastCli::LiveBroadcastStart() const {
  return LiveBroadcastClient::GetInstance().LiveBroadcastStart();
}
tl::expected<LiveBroadcastStateInfo, InsErrorCode> InsLivecastCli::LiveBroadcastGetState() const { ... }

// ② set_url：校验 → 写 configd → 【读回比对】三段式（写路径带自证）
InsErrorCode InsLivecastCli::SetLiveBroadcastUrl(const std::string& rtmp_url) const {
  const std::string trimmed = StringHelper::Trim(rtmp_url);
  if (auto v = ValidateRtmpUrl(trimmed); v != kInsErrorCode_Comm_Success) return v;
  // ValidateRtmpUrl 内部三关：非空 / rtmp://|rtmps:// 前缀 / < kMaxRtmpAddressLen
  bll::ConfigParamController::GetInstance().SetGeneralConfig<ConfigKey::kLiveBroadcast>(...);
  // 读回比对：期望值 != 实际存储 → kInsErrorCode_Comm_Eio（防配置缓冲区截断静默失败）
  if (stored_url != trimmed) return kInsErrorCode_Comm_Eio;
  return kInsErrorCode_Comm_Success;
}

// ③ set_connect_wifi 双路径：有密码全量连接 / 无密码复用已存配置
InsErrorCode InsLivecastCli::SetConnectWifi(const std::string& ssid,
                                            const std::string& password) const {
  if (password.empty())
    return NetdWifiStaClient::GetInstance().WifiStaOnNoPasswd(
        OperateOwner::kLive, OperateMode::kAsync, ssid, "");
  return NetdWifiStaClient::GetInstance().WifiStaOn(
      OperateOwner::kLive, OperateMode::kAsync, ssid, password, "", WifiChannel::kChannelAuto);
}
```

**要点**：`set_url` 的**写后读回校验**（read-back verify）是维测工具可靠性设计——配置写入可能被固定数组截断，只有读回一致才算成功；`kAsync` 模式返回码仅表示"已提交"，与服务端"受理"契约一致。

#### 片段 4：维测入口的动态地址初始化（`cli/source/main.cc`，排障故事三的修复实锤）
```cpp
InsErrorCode InitializeIbus() {
  std::vector<std::unique_ptr<::erpc::Service>> services;   // 空 service 列表
  // 第二参 nullptr → 由 ibus 分配动态地址（非静态枚举绑定）
  // 彻底消除与设备上其他节点的固定地址/枚举偏移冲突
  return ::ins::ibus::IbusService::GetInstance().Initialize(
      std::move(services), nullptr);
}
int main() {
  if (InitializeIbus() != kInsErrorCode_Comm_Success) { ... return -1; }
  CommandManager::GetInstance().InitializeCommands();  // 注册4命令
  CliTerminal terminal(true);                          // replxx + 历史持久化
  while (auto input = terminal.Input("ins-livecast> ")) {
    if (!terminal.HandleLine(*input)) break;
  }
}
```

**replxx 真实配置（`cli/source/cli_terminal.cc:61-95`）**：`set_max_history_size(100)`、`set_max_hint_rows(4)`、completion/hint/highlighter 三回调挂载、`Ctrl+R` 反向历史搜索、`Ctrl+L` 清屏、历史持久化到 `$HOME/.config/ins_livecast_cli/history.txt`（目录缺失时降级为不持久化，不阻塞启动）。

**命令注册表（`cli/source/command_manager.cc:83-86`）**：`LiveCtrlCommand`（prepare/start/stop/resume/cancel/set_url/set_connect_wifi 七子命令，`live_ctrl_command.cc:103-143` 分发）+ `LiveInfoCommand`（get_state）+ `HelpCommand` + `QuitCommand`。

**受理契约在 CLI 输出中的体现（`live_ctrl_command.cc:53-73`）**：
- 成功输出 `"xxx request accepted."` + 固定提示 `"请求已受理，请使用 get_state 确认最终状态。"` ——把"Success≠完成"的异步契约**外化成工具话术**，杜绝维测人员误判；
- `kInsErrorCode_Ibus_Timeout` 时定向打印 `"Please check whether ins_livecast is running..."` ——超时提示直接指向最常见根因（主进程未起）。

