189	      ILOGS_E << "Set Last Connected Wifi SSID failed: "
190	              << ins::errc::GetInsErrorCodeString(ret);
191	      return ret;
192	    }
193	    {
194	      ins::base::AutoMutex lock(config_mutex_);
195	      LiveBroadcastConfig updated = *current_config_;
196	      updated.last_connected_ssid = stored_ssid;
197	      current_config_ =
198	          std::make_shared<LiveBroadcastConfig>(std::move(updated));
199	    }
200	    ILOGS_I << "Save Connected WiFi success";
201	  } else {
202	    ILOGS_E << "Save Connected WiFi rejected: sta_status is not connected";
203	    return kInsErrorCode_Comm_Einval;
204	  }
205	  return kInsErrorCode_Comm_Success;
206	}
