/**
 * @brief WiFi 连接状态（与 netd StaStatus 对应，避免头文件依赖 netd IDL）
 */
enum class WifiConnectionState {
  kDisabled,      ///< 禁用
  kDisconnected,  ///< 未连接
  kConnecting,    ///< 连接中
  kConnected,     ///< 已连接
  kDisconnecting  ///< 断开中
};

/**
 * @brief 当前 WiFi 连接状态信息
 */
struct WifiConnectionStatus {
  WifiConnectionState state = WifiConnectionState::kDisconnected;  ///< 连接状态
  std::string ssid;        ///< 当前 STA SSID（已连接时有效）
  std::string bssid;       ///< 当前 STA BSSID（已连接时有效）
  int32_t error_code = 0;  ///< 最近一次连接结果码（0 表示成功/无错误）
};

/**
 * @brief 网络控制器
 * @details 负责WIFI配网和连接
 * @note 不可复制，仅可移动（管理网络连接状态）
 */
class NetworkController {
 public:
  NetworkController();
  ~NetworkController();

  // 禁止拷贝
  NetworkController(const NetworkController&) = delete;
  NetworkController& operator=(const NetworkController&) = delete;

  // 允许移动
  NetworkController(NetworkController&&) = default;
  NetworkController& operator=(NetworkController&&) = default;

  /**
   * @brief 初始化网络控制器
   */
  InsErrorCode Initialize();

  /**
   * @brief 请求连接指定 WIFI（仅提交 RPC，不等待连接完成）
   * @param ssid SSID
   * @return 仅表示 RPC 提交是否成功（kInsErrorCode_Comm_Success
   * 表示请求已发出）。 实际的连接成功/失败由 IBus netd 主题回调通知（如
   * OnTopicWifiStaOn），
   *         需通过事件/回调传递给状态机，调用方不可将本返回值视为“已连接”。
   */
  InsErrorCode RequestConnectWifi(const std::string& ssid);

  /**
   * @brief 请求断开 WIFI（仅提交 RPC，不等待断开完成）
   * @return 仅表示 RPC 提交是否成功。实际断开完成由 IBus netd 主题回调通知，
   *         调用方不可将本返回值视为“已断开”。
   */
  InsErrorCode RequestDisconnectWifi();

  /**
   * @brief 获取当前 WiFi 连接状态（同步查询 netd）
   * @param out_status 输出当前 STA 连接状态与信息，不可为 nullptr
   * @return kInsErrorCode_Comm_Success 表示查询成功，out_status 已填充；
   *         失败时返回错误码，out_status->state 会被置为 kDisconnected
   */
  InsErrorCode GetCurrentWifiStatus(WifiConnectionStatus* out_status);
};

