// Copyright (c) 2025 Insta360. All rights reserved.

#include "controller/network_controller.h"

#include "camera_netd_client.h"
#include "common_netd_common.h"
#include "ins_base/log.h"
#include "ins_error_code_string.h"

namespace ins {
namespace live_broadcast {

namespace {
#ifdef LOG_TAG
#undef LOG_TAG
#endif
#define LOG_TAG "NetworkController"
}  // namespace

NetworkController::NetworkController() = default;

NetworkController::~NetworkController() = default;

InsErrorCode NetworkController::Initialize() {
  return kInsErrorCode_Comm_Success;
}

InsErrorCode NetworkController::RequestConnectWifi(const std::string& ssid) {
  if (ssid.empty()) {
    ILOGS_E << "RequestConnectWifi rejected: empty SSID";
    return kInsErrorCode_Comm_Einval;
  }
  ILOGS_I << "SSID: " << ssid;
  // 异步 RPC：仅提交连接请求，实际连接结果由 IBus OnTopicWifiStaOn 等回调通知
  InsErrorCode ret =
      ins::ibus::camera::netd::NetdWifiStaClient::GetInstance()
          .WifiStaOnNoPasswd(ins::ibus::common::netd::OperateOwner::kLive,
                             ins::ibus::common::netd::OperateMode::kAsync, ssid,
                             "");
  if (ret != kInsErrorCode_Comm_Success) {
    ILOGS_E << "WifiStaOnNoPasswd RPC failed: "
            << ins::errc::GetInsErrorCodeString(ret);
    return ret;
  }
  ILOGS_I << "WifiStaOnNoPasswd RPC submitted";
  return kInsErrorCode_Comm_Success;
}

InsErrorCode NetworkController::RequestDisconnectWifi() {
  // 异步 RPC：仅提交断开请求，实际断开完成由 IBus netd 主题回调通知
  InsErrorCode ret =
      ins::ibus::camera::netd::NetdWifiStaClient::GetInstance().WifiStaOff(
          ins::ibus::common::netd::OperateOwner::kLive,
          ins::ibus::common::netd::OperateMode::kAsync);
  if (ret != kInsErrorCode_Comm_Success) {
    ILOGS_E << "WifiStaOff RPC failed: "
            << ins::errc::GetInsErrorCodeString(ret);
    return ret;
  }
  ILOGS_I << "WifiStaOff RPC submitted";
  return kInsErrorCode_Comm_Success;
}

InsErrorCode NetworkController::GetCurrentWifiStatus(
    WifiConnectionStatus* out_status) {
  if (out_status == nullptr) {
    ILOGS_E << "out_status is nullptr";
    return kInsErrorCode_Comm_Einval;
  }

  out_status->state = WifiConnectionState::kDisconnected;
  out_status->ssid.clear();
  out_status->bssid.clear();
  out_status->error_code = 0;

  auto wifi_info_ret =
      ins::ibus::camera::netd::NetdWifiUtilsClient::GetInstance()
          .WifiUtilsGetAllInfo(ins::ibus::common::netd::OperateOwner::kLive);

  if (!wifi_info_ret.has_value()) {
    ILOGS_E << "WifiUtilsGetAllInfo failed: "
            << ins::errc::GetInsErrorCodeString(wifi_info_ret.error());
    return wifi_info_ret.error();
  }

  const auto& info = wifi_info_ret.value();
  using StaStatus = ins::ibus::common::netd::StaStatus;

  switch (info.wifi_status.sta_status) {
    case StaStatus::kDisabled:
      out_status->state = WifiConnectionState::kDisabled;
      break;
    case StaStatus::kDisconnected:
      out_status->state = WifiConnectionState::kDisconnected;
      break;
    case StaStatus::kConnecting:
      out_status->state = WifiConnectionState::kConnecting;
      break;
    case StaStatus::kConnected:
      out_status->state = WifiConnectionState::kConnected;
      out_status->ssid = info.sta_info.ssid;
      out_status->bssid = info.sta_info.bssid;
      break;
    case StaStatus::kDisconnecting:
      out_status->state = WifiConnectionState::kDisconnecting;
      break;
    default:
      out_status->state = WifiConnectionState::kDisconnected;
      break;
  }

  out_status->error_code = static_cast<int32_t>(info.wifi_status.sta_errorcode);

  return kInsErrorCode_Comm_Success;
}

}  // namespace live_broadcast
}  // namespace ins

 * @note 会发布错误码Topic
 */
void ReportLiveBroadcastErrorCode(LiveBroadcastErrorCode error_code);

/**
 * @brief 启动时长计时器（由Running状态调用）
 */
void StartLiveBroadcastDurationTimer();

/**
 * @brief 停止时长计时器（由Stopping状态调用）
 */
void StopLiveBroadcastDurationTimer();

/**
