#### 5. running.cc EventError — network reconnect

```cpp
void LiveStateRunning::OnEvent(const EventError& event) {
  ILOGS_E << "Received EventError in Running state, error_code="
          << static_cast<int32_t>(event.error_code)
          << ", message=" << event.message;

  // 网络错误：有限次数自动重连；超过阈值后按异常停播处理（保存续播记录并停播）
  if (event.error_code == LiveBroadcastErrorCode::kNetworkError) {
    ++network_reconnect_attempts_;
    ILOGS_W << "Network error detected, reconnect attempt "
            << network_reconnect_attempts_ << "/" << kMaxNetworkReconnectAttempts;

    if (network_reconnect_attempts_ <= kMaxNetworkReconnectAttempts) {
      if (config_manager_ && network_controller_) {
        const std::string saved_ssid = config_manager_->GetLastConnectedSsid();
        if (!saved_ssid.empty()) {
          // 异步提交重连请求；结果由 netd WifiStaOn/Off Topic 异步通知，
          // 若链路恢复但 RTMP 会话已死，由 LiveMonitor 的后续错误事件驱动停播。
          network_controller_->RequestConnectWifi(saved_ssid);
        }
      }
      return;  // 保留在 Running，等待链路恢复
    }

    ILOGS_E << "Network reconnect attempts exceeded, stopping with resume record";
    if (resume_manager_ &&
        ShouldSaveResumeRecord(LiveBroadcastStopReason::kNetworkError)) {
      const uint32_t duration = manager_ ? manager_->GetLiveDuration() : 0;
      resume_manager_->SaveResumeRecord(LiveBroadcastStopReason::kNetworkError, duration);
    }
    ChangeState<LiveStateStopping>();
    return;
  }

  // 其他错误（过热/系统错误等），保存续播记录并进入Stopping状态
  if (resume_manager_ &&
      ShouldSaveResumeRecord(LiveBroadcastStopReason::kSystemError)) {
    const uint32_t duration = manager_ ? manager_->GetLiveDuration() : 0;
    resume_manager_->SaveResumeRecord(LiveBroadcastStopReason::kSystemError, duration);
  }
  ChangeState<LiveStateStopping>();
}
