#pragma once

#include <memory>

#include "ins_error_code/ins_errorcode.h"
#include "muxer/flv_muxer.h"

namespace ins {
namespace live_broadcast {

class ConfigManager;

/**
 * @brief 流控制器
 * @details 负责切换直播模式和启动/停止直播流
 * @note 不可复制，仅可移动（管理流状态和资源）
 */
class StreamController {
 public:
  StreamController();
  ~StreamController();

  // 禁止拷贝
  StreamController(const StreamController&) = delete;
  StreamController& operator=(const StreamController&) = delete;

  // 允许移动
  StreamController(StreamController&&) = default;
  StreamController& operator=(StreamController&&) = default;

  /**
   * @brief 初始化流控制器
   */
  InsErrorCode Initialize();

  /**
   * @brief 切换到直播模式
   */
  InsErrorCode SwitchToLiveMode();

  /**
   * @brief 启动直播流
   */
  InsErrorCode StartLiveStream();

  /**
   * @brief 停止直播流
   */
  InsErrorCode StopLiveStream();

  /**
   * @brief 设置配置管理器（用于获取/设置编码类型等）
   * @param manager ConfigManager 实例，由 Manager 在初始化时注入
   */
  void SetConfigManager(std::shared_ptr<ConfigManager> manager) {
    config_manager_ = std::move(manager);
  }

 private:
  /** FLV 封装器，用于 RTMP 推流时设置编码格式（当前仅使用 H.264） */
  FlvMuxer muxer_;
  /** 配置管理器，由外部注入，用于读写编码类型等配置 */
  std::shared_ptr<ConfigManager> config_manager_;
};

}  // namespace live_broadcast
}  // namespace ins

