// 时长计时器

#pragma once

#include <atomic>
#include <cstdint>  // for uint32_t
#include <functional>
#include <memory>

#include "ins_base/time/time_types.h"
#include "ins_error_code/ins_errorcode.h"

namespace ins::base {
class Timer;
}  // namespace ins::base

namespace ins {
namespace live_broadcast {

/**
 * @brief 直播时长计时器
 * @details 使用 ins::base::Timer 周期 1 秒触发，
 *          在回调中递增时长并调用用户回调发布时长更新。
 * @note 不可复制、不可移动（含 Timer 等不可移动成员）。
 *       生命周期须由 shared_ptr 管理，创建请使用 Create()，Timer 回调内通过
 *       weak_ptr lock 避免 owner 析构时的 use-after-free。Stop() 为异步停止，
 *       成功返回不表示回调已退出；若需在释放回调所引用资源前等待回调结束，请使用
 *       StopAndWait(timeout)。
 */
class DurationTimer : public std::enable_shared_from_this<DurationTimer> {
 public:
  /// 时长更新回调函数类型（参数为当前时长，单位：秒）
  using DurationCallback = std::function<void(uint32_t)>;

  /// 周期定时器间隔（毫秒）
  static constexpr int32_t kDurationTimerIntervalMs = 1000;

  /**
   * @brief 工厂方法：创建由 shared_ptr 管理的 DurationTimer（唯一合法创建入口）
   * @param callback 时长更新回调函数（每秒调用一次）
   * @return 已完成 InitTimer() 的实例的 shared_ptr，调用方需持有时计时器才有效
   * @note 构造函数为 private，禁止外部通过构造或 make_shared 绕开本工厂，避免
   *       半初始化（duration_timer_ 未创建）导致 Start() 等运行时错误。
   */
  static std::shared_ptr<DurationTimer> Create(DurationCallback callback);

  ~DurationTimer();

  // 禁止拷贝
  DurationTimer(const DurationTimer&) = delete;
  DurationTimer& operator=(const DurationTimer&) = delete;

  // 禁止移动
  DurationTimer(DurationTimer&&) = delete;
  DurationTimer& operator=(DurationTimer&&) = delete;

  /**
   * @brief 启动计时器
   */
  InsErrorCode Start();

  /**
   * @brief 停止计时器（异步，不等待回调退出）
   * @details 内部使用 timeout=0 调用底层 Timer::Stop，即立即返回且**不等待**
   *          “当前正在执行的回调”结束。返回成功仅表示已请求停止、后续不再触发，
   *          **不保证回调已退出**。若在释放回调所引用的外部资源前需确保回调已结束，
   *          请使用 StopAndWait(timeout)。
   * @return 底层 Timer::Stop(0) 的返回值
   * @retval kInsErrorCode_Comm_Success 已请求停止（回调可能仍在执行）
   * @retval kInsErrorCode_Comm_Ealready
   * 已处于未运行或已停止（不保证回调已结束）
   */
  InsErrorCode Stop();

  /**
   * @brief 停止计时器并等待回调退出（最多等待指定时长）
   * @param timeout 等待“当前正在执行的回调”结束的最大时长（纳秒）；0 表示不等待
   *                （与 Stop() 行为一致），>0 时底层会等待回调结束或超时
   * @return 底层 Timer::Stop(timeout) 的返回值
   * @retval kInsErrorCode_Comm_Success 已停止且回调已结束（或未在运行）
   * @retval kInsErrorCode_Comm_Ealready 已处于未运行或已停止（不保证本次调用时
   *         回调已结束，参见 ins::base::Timer::Stop 文档）
   * @retval kInsErrorCode_Comm_Etimedout 等待回调结束超时，回调可能仍在执行
   */
  InsErrorCode StopAndWait(ins::base::Stdns_t timeout);

  /**
   * @brief 获取当前时长（秒）
   */
  uint32_t GetDuration() const;
  /**
   * @brief 获取计时器是否正在运行
   * @return 是否正在运行
   */
  bool IsRunning() const;

 private:
  /**
   * @brief 构造函数（仅供 Create 内部使用；外部必须通过 Create() 获取实例）
   * @param callback 时长更新回调函数
   */
  explicit DurationTimer(DurationCallback callback);

  /**
   * @brief 在对象已被 shared_ptr 持有后注册 Timer（回调捕获 weak_ptr）；仅由
   *        Create() 在工厂路径中调用，确保所有对外可见实例均已完成内部 Timer
   * 注册。
   */
  void InitTimer();

  /**
   * @brief 周期 Timer 回调：递增时长并调用用户回调发布
   */
  void OnTimerTick();

 private:
  /// 时长更新回调
  DurationCallback callback_;
  /// 运行标志
  std::atomic<bool> running_{false};
  /// 时长计数（秒）
  std::atomic<uint32_t> duration_seconds_{0};
  /// 周期定时器（1 秒触发）
  std::unique_ptr<ins::base::Timer> duration_timer_;
};

}  // namespace live_broadcast
}  // namespace ins

