31	// 直播续播场景的最小必要校验：
32	// - 空 SSID 表示“未记录上次 WiFi”，属于合法哨兵值
33	// - 非空 SSID 仅允许 ASCII 可打印字符，长度不超过 32 字节
34	
35	bool IsStoredSsidLegal(const std::string& ssid) {
36	  if (ssid.empty()) {
37	    return false;
38	  }
39	  if (ssid.size() > ::ins::config::kLiveBroadcastMaxSsidLength - 1) {
40	    return false;
41	  }
42	  // 禁止包含换行符和不可见控制字符
43	  for (char ch : ssid) {
44	    const unsigned char c = static_cast<unsigned char>(ch);
45	    if (c < static_cast<unsigned char>(0x20) ||
46	        c == static_cast<unsigned char>(0x7F)) {
47	      return false;  // 可选，增强安全
48	    }
49	  }
50	  return true;
51	}
52	
53	// 对从 configd 读出的配置做合法性校验，非法字段就地清空，避免下游使用异常数据
54	void SanitizeLoadedConfig(::ins::config::LiveBroadcastConfig* cfg) {
55	  if (cfg == nullptr) {
56	    return;
57	  }
58	  const size_t rtmp_address_len =
59	      strnlen(cfg->rtmp_address.data(), cfg->rtmp_address.size());
60	  if (rtmp_address_len == cfg->rtmp_address.size() && rtmp_address_len > 0) {
61	    ILOGS_W << "rtmp_address rejected: length is not valid " << rtmp_address_len
62	            << " > " << cfg->rtmp_address.size() - 1;
63	    cfg->rtmp_address.fill('\0');
64	  }
65	
66	  const size_t ssid_len =
67	      strnlen(cfg->last_connected_ssid.data(), cfg->last_connected_ssid.size());
68	  if (ssid_len == cfg->last_connected_ssid.size() && ssid_len > 0) {
69	    ILOGS_W << "ssid rejected: length is not valid " << ssid_len << " > "
70	            << cfg->last_connected_ssid.size() - 1;
71	    cfg->last_connected_ssid.fill('\0');
72	  } else {
73	    std::string ssid_str(cfg->last_connected_ssid.data(), ssid_len);
74	    if (!IsStoredSsidLegal(ssid_str)) {
75	      ILOGS_W << "ssid is not legal: " << ssid_str;
76	      cfg->last_connected_ssid.fill('\0');
77	    }
78	  }
79	}
80	
81	}  // namespace
82	
83	ConfigManager::ConfigManager()
84	    : current_config_(std::make_shared<LiveBroadcastConfig>()) {}
85	
86	ConfigManager::~ConfigManager() = default;
87	
88	InsErrorCode ConfigManager::Initialize() {
89	  InsErrorCode ret = LoadConfigFromConfigd();
90	  if (ret != kInsErrorCode_Comm_Success) {
91	    ILOGS_E << "LoadConfigFromConfigd failed: "
92	            << ins::errc::GetInsErrorCodeString(ret);
93	    return ret;
94	  }
95	  ILOGS_I << "ConfigManager initialized, config loaded from configd";
96	  return kInsErrorCode_Comm_Success;
97	}
98	
99	InsErrorCode ConfigManager::LoadConfigFromConfigd() {
100	  auto live_broadcast_cfg =
101	      ::ins::bll::ConfigController::GetInstance()
102	          .GetConfig<::ins::config::ConfigKey::kLiveBroadcast>();
103	  if (!live_broadcast_cfg.has_value()) {
104	    ILOGS_W << "GetConfig kLiveBroadcast failed: "
105	            << ins::errc::GetInsErrorCodeString(live_broadcast_cfg.error());
106	    return live_broadcast_cfg.error();
107	  }
108	
109	  // 先写入新对象，再原子替换，避免读者看到半更新状态
110	  ::ins::config::LiveBroadcastConfig cfg = live_broadcast_cfg.value();
111	  SanitizeLoadedConfig(&cfg);
112	  auto new_config = std::make_shared<LiveBroadcastConfig>(std::move(cfg));
113	  {
114	    ins::base::AutoMutex lock(config_mutex_);
115	    current_config_ = std::move(new_config);
116	  }
117	  return kInsErrorCode_Comm_Success;
118	}
119	
120	std::shared_ptr<const LiveBroadcastConfig> ConfigManager::GetConfig() const {
121	  ins::base::AutoMutex lock(config_mutex_);
122	  return current_config_;
123	}
124	
125	// 由 Manager::OnConfigUpdate 在收到 Config Topic
126	// 变更时调用，调用方传入当前状态。 直播状态为 kRunning 时不允许重新载入；非
127	// kRunning 时立即重载配置。
128	// 直播状态为Running时，重载也不会生效，转为Idle状态时会重载配置一次
129	void ConfigManager::OnConfigChanged(LiveBroadcastState current_state) {
130	  if (current_state == LiveBroadcastState::kRunning) {
131	    ILOGS_I << "Config changed, skip reload when live state is Running";
132	    return;
133	  }
134	  InsErrorCode ret = LoadConfigFromConfigd();
135	  if (ret == kInsErrorCode_Comm_Success) {
136	    ILOGS_I << "Config reloaded on change";
137	  } else {
138	    ILOGS_E << "Config reload failed: "
139	            << ins::errc::GetInsErrorCodeString(ret);
140	  }
141	}
142	
143	std::string ConfigManager::GetRtmpUrl() const {
144	  ins::base::AutoMutex lock(config_mutex_);
145	  const auto& rtmp = current_config_->rtmp_address;
146	  const size_t len = strnlen(rtmp.data(), rtmp.size());
147	  if (len == rtmp.size() && len > 0) {
148	    return {};
149	  }
150	  return std::string(rtmp.data(), len);
151	}
