  auto result = work_msg_looper_->PostAndWaitResponse<InsErrorCode>(
      MessageIds::kDispatchPrepare, 0);
  if (!result.has_value()) {
    ILOGS_E << "PostAndWaitResponse failed: "
            << ins::errc::GetInsErrorCodeString(result.error());
    return result.error();
  }
  return result.value();
}

