**5. `live_state_prepare.cc` OnEntry** — implement WiFi config read + reconnect request:
```cpp
void LiveStatePrepare::OnEntry() {
  ILOGS_I << "Entering Prepare state";

  if (!config_manager_ || !network_controller_) {
    ILOGS_E << "ConfigManager/NetworkController not set";
    return;
  }

  // 读取上次连接的 WiFi 配置（进入 Running 时由 SaveConnectedWifiSsid落盘）
  const std::string saved_ssid = config_manager_->GetLastConnectedSsid();
  if (saved_ssid.empty()) {
    ILOGS_W << "No saved WiFi config, waiting for provisioning";
    return;
  }

  WifiConnectionStatus wifi_status{};
  const InsErrorCode ret = network_controller_->GetCurrentWifiStatus(&wifi_status);
  if (ret == kInsErrorCode_Comm_Success &&
      wifi_status.state == WifiConnectionState::kConnected) {
    ILOGS_I << "WiFi already connected: " << wifi_status.ssid;
    return;  // 等 EventStartRequest 或 EventPrepareComplete 驱动后续
  }

  // 未连接：异步请求连接上次的 AP，结果经 netd Topic → EventPrepareComplete
  InsErrorCode req_ret = network_controller_->RequestConnectWifi(saved_ssid);
  if (req_ret != kInsErrorCode_Comm_Success) {
    ILOGS_E << "RequestConnectWifi(" << saved_ssid << ") failed: "
            << ins::errc::GetInsErrorCodeString(req_ret);
  } else {
    ILOGS_I << "WiFi reconnect requested for saved AP (async)";
  }
}
