std::string ConfigManager::GetRtmpUrl() const {
  ins::base::AutoMutex lock(config_mutex_);
  const auto& rtmp = current_config_->rtmp_address;
  const size_t len = strnlen(rtmp.data(), rtmp.size());
  if (len == rtmp.size() && len > 0) {
    return {};
  }
  return std::string(rtmp.data(), len);
}

input.new_string:
std::string ConfigManager::GetRtmpUrl() const {
  ins::base::AutoMutex lock(config_mutex_);
  const auto& rtmp = current_config_->rtmp_address;
  const size_t len = strnlen(rtmp.data(), rtmp.size());
  if (len == rtmp.size() && len > 0) {
    return {};
  }
  return std::string(rtmp.data(), len);
}

std::string ConfigManager::GetLastConnectedSsid() const {
  ins::base::AutoMutex lock(config_mutex_);
  const auto& ssid = current_config_->last_connected_ssid;
  const size_t len = strnlen(ssid.data(), ssid.size());
  if (len == ssid.size() && len > 0) {
    return {};  // 非法记录（已在 SanitizeLoadedConfig 处理过，此处兜底）
  }
  return std::string(ssid.data(), len);
}

