InsErrorCode StreamController::StartLiveStream() {
  auto& pipeline_client =
      ins::ibus::camera::mediad::MediadPipelineClient::GetInstance();
  InsErrorCode start_ret = pipeline_client.PipelineStartStream(
      ins::ibus::camera::mediad::MediadStreamType::kStreamTypeWifi);
  if (start_ret != kInsErrorCode_Comm_Success) {
    ILOGS_W << "Failed to start WIFI liveview, error="
            << ins::errc::GetInsErrorCodeString(start_ret);
  } else {
    ILOGS_I << "Started WIFI liveview successfully";
  }
