// Copyright (c) 2025 Insta360. All rights reserved.

#include "timer/duration_timer.h"

#include "ins_base/log.h"
#include "ins_base/time/timer.h"
#include "ins_base/time/timer_types.h"
#include "ins_error_code_string.h"
constexpr int64_t kStopAndWaitTimeoutSec = 2;

namespace ins {
namespace live_broadcast {

namespace {
#ifdef LOG_TAG
#undef LOG_TAG
#endif
#define LOG_TAG "DurationTimer"
}  // namespace

std::shared_ptr<DurationTimer> DurationTimer::Create(
    DurationCallback callback) {
  // 必须用 new 再包装为 shared_ptr：构造函数为 private，make_shared 会在标准库
  // allocator 内调用构造，该上下文无法访问私有构造；本成员函数内 new 可访问。
  // 先构造并托管再 InitTimer()，保证 InitTimer() 内 weak_from_this() 有效。
  std::shared_ptr<DurationTimer> p(new DurationTimer(std::move(callback)));
  p->InitTimer();
  return p;
}

DurationTimer::DurationTimer(DurationCallback callback)
    : callback_(std::move(callback)) {
  ILOGS_I << "DurationTimer created";
}

void DurationTimer::InitTimer() {
  // 仅由 Create() 在 make_shared 之后调用，此时已由 shared_ptr
  // 托管，weak_from_this() 安全；lambda 内 lock() 失败表示 owner
  // 已析构，直接返回避免 UAF。
  std::weak_ptr<DurationTimer> weak = weak_from_this();
  duration_timer_ = std::make_unique<ins::base::Timer>(
      "live_broadcast_duration_timer", ins::base::kTimerTypePeriod, [weak]() {
        auto self = weak.lock();
        if (!self) {
          return;
        }
        self->OnTimerTick();
      });
}

DurationTimer::~DurationTimer() {
  // 析构仅调用 Stop()（不等待回调）；回调内通过 weak_ptr 保护避免 UAF。
  // 若需在释放回调所引用的外部资源前确保回调已结束，调用方应先调用
  // StopAndWait(timeout) 再析构本对象或释放该资源。
  const InsErrorCode stop_ret = Stop();
  if (stop_ret != kInsErrorCode_Comm_Success &&
      stop_ret != kInsErrorCode_Comm_Ealready) {
    ILOGS_W
        << "DurationTimer destroyed with Stop() result: "
        << ins::errc::GetInsErrorCodeString(stop_ret)
        << "; callback may still be in flight, relying on weak_ptr in callback";
  }
  ILOGS_I << "DurationTimer destroyed";
}

InsErrorCode DurationTimer::Start() {
  if (running_.load()) {
    ILOGS_W << "DurationTimer already running";
    return kInsErrorCode_Comm_Success;
  }

  if (!duration_timer_ || !duration_timer_->IsValid()) {
    ILOGS_E << "DurationTimer invalid, cannot start";
    return duration_timer_ ? duration_timer_->InitResult()
                           : kInsErrorCode_Comm_Efault;
  }

  ILOGS_I << "Starting DurationTimer";

  duration_seconds_.store(0);
  running_.store(true);

  const InsErrorCode ret = duration_timer_->Start(
      ins::base::stdms(static_cast<int64_t>(kDurationTimerIntervalMs)));
  if (ret != kInsErrorCode_Comm_Success) {
    running_.store(false);
    ILOGS_E << "DurationTimer Start failed: "
            << ins::errc::GetInsErrorCodeString(ret);
    return ret;
  }

  ILOGS_I << "DurationTimer started";
  return kInsErrorCode_Comm_Success;
}

InsErrorCode DurationTimer::Stop() {
  return StopAndWait(ins::base::stdns(kStopAndWaitTimeoutSec * 1000000000));
}

InsErrorCode DurationTimer::StopAndWait(ins::base::Stdns_t timeout) {
  if (!running_.load()) {
    return kInsErrorCode_Comm_Ealready;
  }

  ILOGS_I << "Stopping DurationTimer";

  running_.store(false);

  InsErrorCode ret = kInsErrorCode_Comm_Success;
  if (duration_timer_) {
    ret = duration_timer_->Stop(timeout);
    if (ret != kInsErrorCode_Comm_Success &&
        ret != kInsErrorCode_Comm_Ealready) {
      ILOGS_W << "DurationTimer underlying Stop returned: "
              << ins::errc::GetInsErrorCodeString(ret)
              << "; callback may still be running";
    }
  }

  ILOGS_I << "DurationTimer stopped, total duration: "
          << duration_seconds_.load() << " seconds";
  return ret;
}

uint32_t DurationTimer::GetDuration() const { return duration_seconds_.load(); }
bool DurationTimer::IsRunning() const { return running_.load(); }

void DurationTimer::OnTimerTick() {
  if (!running_.load()) {
    return;
  }

  const uint32_t current_duration = duration_seconds_.fetch_add(1) + 1;

  if (callback_) {
    try {
      callback_(current_duration);
    } catch (const std::exception& e) {
      ILOGS_E << "Duration callback exception: " << e.what();
    } catch (...) {
      ILOGS_E << "Duration callback unknown exception";
    }
  }
}

}  // namespace live_broadcast
}  // namespace ins

