26	bool FillRtmpPacketMeta(StreamPacketType packet_type,
27	                        RtmpPacketHolder* holder) {
28	  if (holder == nullptr) {
29	    return false;
30	  }
31	
32	  switch (packet_type) {
33	    case StreamPacketType::kVideo:
34	      holder->pkt.m_packetType = static_cast<uint8_t>(RtmpPacketType::kVideo);
35	      holder->pkt.m_nChannel = static_cast<int>(RtmpChannelId::kVideo);
36	      holder->pkt.m_headerType = RTMP_PACKET_SIZE_LARGE;
37	      return true;
38	    case StreamPacketType::kAudio:
39	      holder->pkt.m_packetType = static_cast<uint8_t>(RtmpPacketType::kAudio);
40	      holder->pkt.m_nChannel = static_cast<int>(RtmpChannelId::kAudio);
41	      holder->pkt.m_headerType = RTMP_PACKET_SIZE_MEDIUM;
42	      return true;
43	    default:
44	      ILOGS_E << "Unsupported stream packet type: "
45	              << static_cast<int>(packet_type);
46	      return false;
47	  }
48	}
