62	InsErrorCode RtmpPusher::Connect(const std::string& rtmp_url) {
63	  if (!rtmp_session_) {
64	    try {
65	      rtmp_session_ = std::make_unique<RtmpSession>();
66	    } catch (const std::bad_alloc& e) {
67	      ILOGS_E << "Failed to create rtmp session: " << e.what();
68	      return kInsErrorCode_LiveBroadcast_OutOfMemory;
69	    }
70	  }
71	
72	  if (rtmp_session_->IsConnected()) {
73	    ILOGS_I << "rtmp_session_ is already connected";
74	    return kInsErrorCode_Comm_Success;
75	  }
76	
77	  InsErrorCode result = rtmp_session_->Connect(rtmp_url);
78	  if (result == kInsErrorCode_Comm_Success) {
79	    ILOGS_I << "rtmp_session_ connected successfully";
80	  }
81	  return result;
82	}
