84	void RtmpPusher::Disconnect() {
85	  Stop();
86	  if (!rtmp_session_) {
87	    ILOGS_E << "rtmp_session_ is null";
88	    return;
89	  }
90	  rtmp_session_->Reset();
91	}
92	
93	bool RtmpPusher::Run() {
94	  if (!rtmp_session_) {
95	    ILOGS_E << "rtmp_session_ is null";
96	    is_running_.store(false);
97	    return false;
98	  }
99	
100	  if (!is_running_) {
101	    return false;
102	  }
103	
104	  if (!stream_reader_) {
105	    is_running_.store(false);
106	    return false;
107	  }
108	
109	  StreamDataPacket packet;
110	  InsErrorCode result =
111	      stream_reader_->GetFrameBlocking(packet, kStreamReaderTimeoutMs);
112	  if (result != kInsErrorCode_Comm_Success &&
113	      result != kInsErrorCode_LiveBroadcast_NoReadableData) {
114	    ILOGS_E << "Failed to get frame, error: " << result;
115	    is_running_.store(false);
116	    return false;
117	  }
118	
119	  if (packet.payload.empty()) {
120	    // 超时 / 空队列：本轮没数据，让上层继续轮询
121	    return true;
122	  }
123	
124	  if (packet.payload.size() > static_cast<size_t>(kMaxRtmpPacketAllocSize)) {
125	    ILOGS_E << "RTMP payload too large, size=" << packet.payload.size()
126	            << " max=" << kMaxRtmpPacketAllocSize;
127	    return true;
128	  }
129	
130	  RtmpPacketHolder holder;
131	  const int alloc_size = static_cast<int>(packet.payload.size());
132	  if (!RTMPPacket_Alloc(&holder.pkt, alloc_size)) {
133	    ILOGS_E << "RTMPPacket_Alloc failed, size=" << packet.payload.size();
134	    return true;
135	  }
136	
137	  std::memcpy(holder.pkt.m_body, packet.payload.data(),
138	              static_cast<size_t>(alloc_size));
139	  holder.pkt.m_nBodySize = static_cast<uint32_t>(alloc_size);
140	  holder.pkt.m_hasAbsTimestamp = 0;
141	  holder.pkt.m_nTimeStamp = packet.timestamp_ms;
142	
143	  if (!FillRtmpPacketMeta(packet.packet_type, &holder)) {
144	    return true;
145	  }
146	  // ILOGS_W_FRQ(1000) << "Send packet timestamp: " << holder.pkt.m_nTimeStamp;
147	  // stream 只提供传输无关的 payload/timestamp/type；
148	  // 具体 RTMPPacket 组装与发送留在 rtmp 模块内完成。
149	  if (rtmp_session_->SendPreparedPacket(holder) != kInsErrorCode_Comm_Success) {
