namespace ins {
namespace live_broadcast {

class StreamController;
/**
 * @brief RTMP推流器
 * @details 负责RTMP连接和音视频帧推流
 * 生命周期契约：
 * - Connect(): 建立RTMP连接。若已断开可再次调用复用。
 * - Start(): 启动推流线程。
 * - Stop(): 停止推流线程（幂等，可安全多次调用）。
 * - Disconnect(): 停止推流线程并断开连接。
 * - 析构函数：保证 Stop() 和 Disconnect() 被调用，安全释放所有资源。
 * @note 不可复制、不可移动（线程回调绑定了this指针，移动会导致悬垂引用）
 */
class RtmpPusher {
 public:
  RtmpPusher();
  ~RtmpPusher();

  // 禁止拷贝
  RtmpPusher(const RtmpPusher&) = delete;
  RtmpPusher& operator=(const RtmpPusher&) = delete;

  // 禁止移动
  RtmpPusher(RtmpPusher&&) = delete;
  RtmpPusher& operator=(RtmpPusher&&) = delete;

  /**
   * @brief 连接RTMP服务器
   */
  InsErrorCode Connect(const std::string& rtmp_url);

  /**
   * @brief 断开RTMP连接
   */
  void Disconnect();

  /**
   * @brief 启动推流线程
   */
  InsErrorCode Start();

  /**
   * @brief 停止推流线程
   */
  void Stop();

  /**
   * @brief 推流线程运行函数
   */
  bool Run();

  /**
   * @brief 设置StreamController
   * @param stream_controller StreamController指针
   */
  void SetStreamController(
      const std::shared_ptr<StreamController>& stream_controller);

  /**
   * @brief 请求取消正在进行的 RTMP 连接
   * @details 该接口会先锁存取消请求；若底层 socket 已建立，会尽力通过
   * shutdown() 打断阻塞中的 RTMP_Connect()/RTMP_ConnectStream()。
   * 它仍不做跨线程 Reset/销毁，调用方在请求取消后，
   * 仍需等待连接线程自行退出。
   */
  void RequestCancelConnect();

 private:
  static constexpr int kStreamReaderTimeoutMs = 200;
  std::unique_ptr<RtmpSession> rtmp_session_;
  std::unique_ptr<StreamReader> stream_reader_;
  std::shared_ptr<StreamController> stream_controller_;

  std::shared_ptr<ins::base::Thread> push_thread_;
  std::atomic<bool> is_running_{false};  // 推流线程是否正在运行
};

