    if (!stall_reported_ && stall_ticks_ >= config::kMonitorStallTicksThreshold) {
      stall_reported_ = true;
      ILOGS_E << "push stalled: no video frames sent for " << stall_ticks_ << "s";
      invoke stall_cb_ (mutex-copied);
    }
  } else {
    stall_ticks_ = 0;
    stall_reported_ = false;
  }
  // ABR 决策（§41.3 阈值 + §19.2五秒持续防抖）
  const BitrateAdvice advice = BitrateAdaptor::Decide(snap.video_fps, kTargetFps, current_bitrate_kbps_, kMin, kMax);
  switch:
 kDecrease: ++low_fps_ticks_; recover_ticks_=0; if (low_ticks >= kLowPersist) { low_ticks=0; ApplyBitrate(advice.target) }
    kIncrease: ++recover_ticks_; low_fps_ticks_=0; if (recover >= kRecoverPersist) { recover=0; ApplyBitrate(advice.target) }
    kNone: reset both counters
