// 码率自适应算法

#pragma once
#include <cstdint>

namespace ins {
namespace live_broadcast {

/// ABR 决策动作
enum class BitrateAction : uint8_t {
  kNone = 0,      ///< 帧率正常，维持当前档位
  kDecrease = 1,  ///< 帧率持续偏低，降低码率档位
  kIncrease = 2,  ///< 帧率持续回稳且未达上限，提升码率档位
};

/// ABR 决策结果
struct BitrateAdvice {
  BitrateAction action = BitrateAction::kNone;
  uint32_t target_bitrate_kbps = 0;  ///< 目标码率档位（仅 action != kNone 有效）
};

/**
 * @brief 码率自适应算法（纯决策，无状态）
 * @details 阈值取自设计文档 AIPL Design.md §41.3：
 *          - fps < 目标×0.7  → 降码率（减半，不低于下限档位）
 *          - fps > 目标×0.95 且未达上限 → 升码率（×1.5，不超过上限档位）
 *          - 其余 → 维持
 *          迟滞带（0.7~0.95）内不动作；连续多 tick 的防抖判定
 *          由调用方 LiveMonitor 负责（低帧 kMonitorLowFpsPersistTicks、
 *          回稳 kMonitorRecoverFpsPersistTicks）。
 * @note 本类无状态，输入一次决策一次，可独立单元测试。
 */
class BitrateAdaptor {
 public:
  BitrateAdaptor() = delete;  // 纯静态工具类，禁止实例化

  /**
   * @brief 根据单次采样给出码率调整建议
   * @param fps 当前每秒发送成功的视频帧数
   * @param target_fps 目标帧率
   * @param current_bitrate_kbps 当前码率档位（kbps）
   * @param min_bitrate_kbps 下限档位（kbps）
   * @param max_bitrate_kbps 上限档位（kbps）
   * @return 决策结果（含目标档位）
   */
  static BitrateAdvice Decide(uint32_t fps, uint32_t target_fps,
                              uint32_t current_bitrate_kbps,
                              uint32_t min_bitrate_kbps,
                              uint32_t max_bitrate_kbps);
};

}  // namespace live_broadcast
}  // namespace ins

// Copyright (c) 2025 Insta360. All rights reserved.

#include "monitor/bitrate_adaptor.h"

namespace ins {
namespace live_broadcast {

namespace {
#ifdef LOG_TAG
#undef LOG_TAG
#endif
#define LOG_TAG "BitrateAdaptor"

// §41.3 阈值：0.7 触发降码率，0.95 触发升码率（百分比因子 ×100 参与整数运算）
constexpr uint32_t kLowFpsPercent = 70;
constexpr uint32_t kRecoverFpsPercent = 95;
constexpr uint32_t kPercentBase = 100;
constexpr uint32_t kDecreaseDivisor = 2;    // 降码率：减半
constexpr uint32_t kIncreaseNumerator = 3;  // 升码率：×1.5
constexpr uint32_t kIncreaseDivisor = 2;
}  // namespace

BitrateAdvice BitrateAdaptor::Decide(uint32_t fps, uint32_t target_fps,
                                     uint32_t current_bitrate_kbps,
                                     uint32_t min_bitrate_kbps,
                                     uint32_t max_bitrate_kbps) {
  BitrateAdvice advice;
  advice.target_bitrate_kbps = current_bitrate_kbps;
  if (target_fps == 0) {
    return advice;  // 配置非法，维持不动
  }

  if (fps * kPercentBase < target_fps * kLowFpsPercent) {
    // 低帧：降码率减半，低于下限档位时收敛到下限
    advice.action = BitrateAction::kDecrease;
    uint32_t target = current_bitrate_kbps / kDecreaseDivisor;
    if (target < min_bitrate_kbps) {
      target = min_bitrate_kbps;
    }
    advice.target_bitrate_kbps = target;
    return advice;
  }

  if (fps * kPercentBase > target_fps * kRecoverFpsPercent &&
      current_bitrate_kbps < max_bitrate_kbps) {
    // 帧率回稳且未达上限：提码率 ×1.5，超过上限时收敛到上限
    advice.action = BitrateAction::kIncrease;
    uint32_t target = current_bitrate_kbps * kIncreaseNumerator / kIncreaseDivisor;
    if (target > max_bitrate_kbps) {
      target = max_bitrate_kbps;
    }
    advice.target_bitrate_kbps = target;
    return advice;
  }

  // 迟滞带内或已达边界：维持
  return advice;
}

}  // namespace live_broadcast
}  // namespace ins

