constexpr uint32_t kBytesPerKilobit = 125;
}  // namespace

NetworkMetrics& NetworkMetrics::GetInstance() {
  static NetworkMetrics instance;
  return instance;
}

void NetworkMetrics::OnVideoFrameSent(uint32_t bytes) {
  video_frames_.fetch_add(1, std::memory_order_relaxed);
  sent_bytes_.fetch_add(bytes, std::memory_order_relaxed);
}

void NetworkMetrics::OnAudioFrameSent(uint32_t bytes) {
  audio_frames_.fetch_add(1, std::memory_order_relaxed);
  sent_bytes_.fetch_add(bytes, std::memory_order_relaxed);
}

NetworkMetrics::Snapshot NetworkMetrics::TakeSnapshot() {
  Snapshot snapshot;
  snapshot.video_fps = video_frames_.exchange(0, std::memory_order_acq_rel);
  snapshot.audio_fps = audio_frames_.exchange(0, std::memory_order_acq_rel);
  const uint32_t bytes = sent_bytes_.exchange(0, std::memory_order_acq_rel);
  snapshot.send_kbps = bytes / kBytesPerKilobit;
  return snapshot;
}

void NetworkMetrics::Reset() {
  video_frames_.store(0, std::memory_order_release);
  audio_frames_.store(0, std::memory_order_release);
  sent_bytes_.store(0, std::memory_order_release);
}

}  // namespace live_broadcast
}  // namespace ins

