  if (!monitor_timer_) {
    // lambda 内只经 this 调用成员；Stop() 与定时器回调由 Timer 内部串行等待
    //（Stop 以超时方式等待回调退出），析构前已 Stop，无 UAF 窗口
    monitor_timer_ = std::make_unique<ins::base::Timer>(
        "live_broadcast_monitor_timer", ins::base::kTimerTypePeriod,
        [this]() { OnMonitorTick(); });
  }
  if (!monitor_timer_->IsValid()) {
    ILOGS_E << "LiveMonitor timer invalid: " << monitor_timer_->InitResult();
    return monitor_timer_->InitResult();
  }

  // 清零上一场直播的残留计数，判定状态全部复位
  NetworkMetrics::GetInstance().Reset();
  current_bitrate_kbps_ = static_cast<uint32_t>(config::kLiveDefaultBitrateKbps);
  low_fps_ticks_ = 0;
  recover_fps_ticks_ = 0;
  stall_ticks_ = 0;
  stall_reported_ = false;

  running_.store(true);
  const InsErrorCode ret = monitor_timer_->Start(
      ins::base::stdms(static_cast<int64_t>(config::kMonitorTickIntervalMs)));
  if (ret != kInsErrorCode_Comm_Success) {
    running_.store(false);
    ILOGS_E << "LiveMonitor Start failed: "
            << ins::errc::GetInsErrorCodeString(ret);
    return ret;
  }
  ILOGS_I << "LiveMonitor started, target_fps=" << config::kLiveTargetFps
          << ", bitrate=" << current_bitrate_kbps_ << "kbps";
  return kInsErrorCode_Comm_Success;
}

void LiveMonitor::Stop() {
  if (!running_.exchange(false)) {
    return;
  }
  if (monitor_timer_) {
    const InsErrorCode ret = monitor_timer_->Stop(
        ins::base::stdns(kStopWaitTimeoutSec * 1000000000LL));
    if (ret != kInsErrorCode_Comm_Success && ret != kInsErrorCode_Comm_Ealready) {
      ILOGS_W << "LiveMonitor timer Stop returned: "
              << ins::errc::GetInsErrorCodeString(ret)
              << "; tick callback may still be running";
    }
  }
  ILOGS_I << "LiveMonitor stopped";
}

void LiveMonitor::SetStallCallback(const StallCallback& callback) {
  ins::base::AutoMutex lock(cb_mutex_);
  stall_callback_ = callback;
}

void LiveMonitor::OnMonitorTick() {
  if (!running_.load()) {
    return;
  }

  const NetworkMetrics::Snapshot snapshot =
      NetworkMetrics::GetInstance().TakeSnapshot();

  // ====== 1. 断流检测：有会话在推但持续没有视频帧发送成功 ======
  if (snapshot.video_fps == 0) {
    ++stall_ticks_;
    if (!stall_reported_ &&
        stall_ticks_ >= static_cast<uint32_t>(config::kMonitorStallTicksThreshold)) {
      stall_reported_ = true;
      ILOGS_E << "Push stalled: no video frame sent for " << stall_ticks_
              << "s, kbps=" << snapshot.send_kbps;
      StallCallback callback;
      {
        ins::base::AutoMutex lock(cb_mutex_);
        callback = stall_callback_;
      }
      if (callback) {
        callback();
      }
    }
  } else {
    stall_ticks_ = 0;
    stall_reported_ = false;  // 帧流恢复，允许下一段停摆再次上报
  }

  // ====== 2. 码率自适应：决策 + 连续 tick 防抖 ======
  const BitrateAdvice advice = BitrateAdaptor::Decide(
      snapshot.video_fps, static_cast<uint32_t>(config::kLiveTargetFps),
      current_bitrate_kbps_, static_cast<uint32_t>(config::kLiveMinBitrateKbps),
      static_cast<uint32_t>(config::kLiveMaxBitrateKbps));

  switch (advice.action) {
    case BitrateAction::kDecrease:
      ++low_fps_ticks_;
      recover_fps_ticks_ = 0;
      if (low_fps_ticks_ >=
          static_cast<uint32_t>(config::kMonitorLowFpsPersistTicks)) {
        low_fps_ticks_ = 0;
        ApplyBitrateAdvice(advice.target_bitrate_kbps);
      }
      break;
    case BitrateAction::kIncrease:
      ++recover_fps_ticks_;
      low_fps_ticks_ = 0;
      if (recover_fps_ticks_ >=
          static_cast<uint32_t>(config::kMonitorRecoverFpsPersistTicks)) {
        recover_fps_ticks_ = 0;
        ApplyBitrateAdvice(advice.target_bitrate_kbps);
      }
      break;
    case BitrateAction::kNone:
    default:
      low_fps_ticks_ = 0;
      recover_fps_ticks_ = 0;
      break;
  }

  ILOGS_D << "monitor tick: fps=" << snapshot.video_fps
          << ", audio_fps=" << snapshot.audio_fps
          << ", kbps=" << snapshot.send_kbps
          << ", bitrate=" << current_bitrate_kbps_ << "kbps"
          << ", stall_ticks=" << stall_ticks_;
}

void LiveMonitor::ApplyBitrateAdvice(uint32_t target_bitrate_kbps) {
  // TODO(待mediad IDL确认): 调用 mediad 码率档位 RPC。设计文档
  // AIPL Design.md §41.3 的调用形式为 mediad_client.SetVideoBitrate(...)，
  // 真实方法名以 camera_mediad.erpc 生成的客户端头文件为准；
  // 在 IDL 接通前只推进本地决策档位并记录日志（advisory-only），
  // 保证算法链路可测、接入时仅需补一行调用。
  ILOGS_W << "ABR advice: bitrate "
          << current_bitrate_kbps_ << " -> " << target_bitrate_kbps
          << " kbps (actuation pending on mediad IDL)";
  current_bitrate_kbps_ = target_bitrate_kbps;
}

}  // namespace live_broadcast
}  // namespace ins

