#define LOG_TAG "LiveBroadcastManager"

// 连接/推流错误码 → 业务错误码映射（错误码规范：配置/参数/资源类归
// SystemError，网络/传输类归 NetworkError；mediad 区间默认按系统错误处理）。
// 错误码取值均来自平台头 ins_errorcode.h，枚举成员以实际头文件为准。
LiveBroadcastErrorCode MapConnectErrorToBusiness(InsErrorCode err) {
  switch (err) {
    case kInsErrorCode_LiveBroadcast_InvalidUrl:
    case kInsErrorCode_LiveBroadcast_SetupUrlFailed:
    case kInsErrorCode_LiveBroadcast_ParamError:
    case kInsErrorCode_LiveBroadcast_InvalidParam:
    case kInsErrorCode_LiveBroadcast_OutOfMemory:
    case kInsErrorCode_LiveBroadcast_InitFailed:
      return LiveBroadcastErrorCode::kSystemError;
    default:
      break;
  }
  if (err >= kInsErrorCode_Range_MediadMin &&
      err <= kInsErrorCode_Range_MediadMax) {
    return LiveBroadcastErrorCode::kSystemError;
  }
  // ConnectFailed / SendFailed / WriteFailed / NotConnected / GetFrameFailed
  // 等传输类错误归网络错误
  return LiveBroadcastErrorCode::kNetworkError;
}

