void LiveBroadcastManager::NotifyMainLooper(LiveBroadcastState state) {
  // 设计裁剪（AIPL Design.md §19.2 原则1）：状态变更一律走
  // ShareState（UpdateShareState）+ StateChanged Topic（PublishStateChanged）
  // 通知消费方，主线程作为 IBus 转发线程不消费状态事件，也未注册任何
  // handler，故不再向主 looper 投递——避免第二条通知通道产生语义分叉。
  ILOGS_D << "Notified main looper of state change to: "
          << magic_enum::enum_name(state);
  static_cast<void>(state);
}

