  const LiveBroadcastState state = GetCurrentState();
  ILOGS_I << "WiFi STA auto-connect on work thread, error_code=" << error_code
          << ", state=" << magic_enum::enum_name(state);

  if (result == ::ins::ibus::common::netd::WifiConnectionResult::kConnectSuccess) {
    if (state == LiveBroadcastState::kPrepare) {
