    const uint32_t ts32 = static_cast<uint32_t>(timestamp_ms);
    for (auto& tag : flv_tags) {
      if (tag.empty()) {
        continue;
      }
      // stream 模块只产出传输无关的数据包；由 rtmp 模块决定如何组装底层
      // RTMPPacket。
      EnqueuePacket(
          StreamDataPacket(std::move(tag), ts32, StreamPacketType::kVideo));
    }
  }
  return kInsErrorCode_Comm_Success;
}

InsErrorCode StreamReader::RunAudio(uint8_t* stream_data, int32_t size,
                                    ins::base::StreamFrameInfo* frame_info) {
  // ====== 音频透传开关（待 AAC 帧格式确认后开启） ======
  // 开启前在入口丢弃音频帧：RtmpPusher 已具备 kAudio RTMP 包发送路径
  // （FillRtmpPacketMeta），但 AAC → FLV Audio Tag 的封装
  // （kFlvAudioTagType=0x08，FLV 规范：SoundFormat=10 AAC + AACPacketType
  // + AudioSpecificConfig）尚未实现；直接把裸 AAC 当音频 Tag 体推送会被
  // 播放器判为坏流。确认 mediad 音频帧格式（ADTS 裸流 / 原始 AAC + ASC，
  // 见 ins::base::StreamFrameInfo 音频字段）后，在 FlvMuxer 补 PackAudioTag
  // 并将本开关置 true 即可接入（设计文档 AIPL Design.md §19/§41.2：
  // stream/ 负责读 H.264/AAC，muxer/ 复用成 FLV）。
  constexpr bool kEnableAudioPassthrough = false;
  if (!kEnableAudioPassthrough) {
    ILOGS_D_FRQ(ins::base::s2ms(5))
        << "audio frame dropped (FLV audio muxing pending)";
    return kInsErrorCode_Comm_Success;
  }

  if (stream_data == nullptr || size <= 0 || frame_info == nullptr) {
    return kInsErrorCode_LiveBroadcast_InvalidStreamData;
  }

  // 时间戳与视频路径同源同基线（first_frame_timestamp_ 保证 A/V 同步），
  // 单调性独立维护（last_audio_timestamp_ms_），不与视频互相钳制
  if (first_frame_timestamp_ == 0) {
    first_frame_timestamp_ = frame_info->pts;
  }
  if (frame_info->pts < first_frame_timestamp_) {
    first_frame_timestamp_ = frame_info->pts;
  }
  uint64_t timestamp_ms = frame_info->pts - first_frame_timestamp_;
  if (timestamp_ms < last_audio_timestamp_ms_) {
    timestamp_ms = last_audio_timestamp_ms_;
  }
  last_audio_timestamp_ms_ = timestamp_ms;

  std::vector<uint8_t> payload(stream_data, stream_data + size);
  EnqueuePacket(StreamDataPacket(std::move(payload),
                                 static_cast<uint32_t>(timestamp_ms),
                                 StreamPacketType::kAudio));
  return kInsErrorCode_Comm_Success;
}

void StreamReader::EnqueuePacket(StreamDataPacket&& packet) {
  const uint32_t ts = packet.timestamp_ms;
  // stream 模块只产出传输无关的数据包；由 rtmp 模块决定如何组装底层
  // RTMPPacket。队满时丢弃队首再重试（实时流取新弃旧）。
  if (!queue_.PostMessage(std::move(packet))) {
    StreamDataPacket drop_packet;
    if (queue_.GetMessage(drop_packet)) {
      ILOGS_W << "StreamReader: queue full, dropped head ts="
              << drop_packet.timestamp_ms;
    } else {
      // 拿不到头部却又入队失败：状态异常（如已 Stop）
      ILOGS_E << "StreamReader: queue full but no head to drop, ts=" << ts;
    }
    if (!queue_.PostMessage(std::move(packet))) {
      ILOGS_E << "StreamReader: retry post failed, ts=" << ts;
    }
  }
}

