    // 设计原则：可恢复的网络错误内化到状态机处理（§19.2）。
    // Running → 重连闭环（WiFi 重关联 + RTMP 重连，超阈值停播）；
    // Prepare → 保持等待重试（见 LiveStatePrepare 的 EventError 分支）
    ReportLiveBroadcastErrorCode(LiveBroadcastErrorCode::kNetworkError);
    LiveStateMachine::DispatchEvent(EventError{
        {}, LiveBroadcastErrorCode::kNetworkError,
        "WiFi STA disconnected (netd WifiStaOff topic)"});
  }
  // Idle/Starting/Stopping：无运行中会话或已在停播路径，仅记录
}
